// A source that FAILED must never look like a source that returned nothing.
// If either side is unreadable, every claim in this window is UNKNOWN - not RECONCILED,
// and not a DELTA either. This node exists because "empty" and "broken" are different facts.
const ok = (pages) => pages.length > 0 && pages.every(p => {
  const s = p.json.statusCode;
  return typeof s === 'number' && s >= 200 && s < 300;
});

const claimPages    = $('Fetch what WE claimed succeeded').all();
const providerPages = $('Fetch what the PROVIDER confirms').all();

const claimsOk   = ok(claimPages);
const providerOk = ok(providerPages);

const codes = (pages) => pages.map(p => p.json.statusCode);

return [{ json: {
  sources_readable: claimsOk && providerOk,
  claims_ok: claimsOk,
  provider_ok: providerOk,
  claim_status_codes: codes(claimPages),
  provider_status_codes: codes(providerPages),
  claim_pages: claimPages.length,
  provider_pages: providerPages.length,
  unreadable_reason: (claimsOk && providerOk) ? null
    : (!claimsOk && !providerOk ? 'BOTH_SOURCES_UNREADABLE'
      : (!claimsOk ? 'CLAIM_SOURCE_UNREADABLE' : 'PROVIDER_SOURCE_UNREADABLE'))
}}];

// Flatten every page of BOTH sources into one comparable shape.
// Pagination matters: a single unpaginated page silently truncates the provider side,
// and truncation looks exactly like a missing confirmation. That is a false alarm generator.
const CLAIM_LIST_PATH    = 'body.data';     // array of your claimed-success rows
const PROVIDER_LIST_PATH = 'body.data';     // array of provider events
const CLAIM_KEY          = 'idempotency_key';
const PROVIDER_KEY       = 'idempotency_key';
const PROVIDER_STATE     = 'status';
const CLAIM_TIME         = 'claimed_at';
const PROVIDER_TIME      = 'occurred_at';

const dig = (o, p) => p.split('.').reduce((x, k) => (x == null ? x : x[k]), o);
const collect = (pages, path) => pages.flatMap(p => {
  const v = dig(p.json, path);
  return Array.isArray(v) ? v : (v ? [v] : []);
});

const claims = collect($('Fetch what WE claimed succeeded').all(), CLAIM_LIST_PATH)
  .map(r => ({ key: r[CLAIM_KEY] ?? null, claimed_at: r[CLAIM_TIME] ?? null, raw: r }));

const events = collect($('Fetch what the PROVIDER confirms').all(), PROVIDER_LIST_PATH)
  .map(e => ({ key: e[PROVIDER_KEY] ?? null, state: e[PROVIDER_STATE] ?? null,
               occurred_at: e[PROVIDER_TIME] ?? null, raw: e }));

// Claims with no shared key cannot be reconciled by anyone. Say so; do not drop them.
const keyless = claims.filter(c => !c.key).length;

return [{ json: { claims, events, claim_count: claims.length,
                  event_count: events.length, keyless_claims: keyless } }];

// The core join. Rule 0: UNKNOWN is never converted to SUCCESS.
// Every claim lands in exactly one bucket, and the bucket names are honest about
// what we actually know - "no event yet" is NOT "the provider rejected it".
const ACCEPT_STATES = ['delivered','accepted','succeeded','confirmed','paid'];
const REJECT_STATES = ['bounced','failed','rejected','canceled','cancelled','refunded'];

const { claims, events, keyless_claims } = $input.first().json;
const win = $('Set reconciliation window and thresholds').first().json;
const overdueMs = (win.overdue_after_minutes ?? 30) * 60 * 1000;
const now = Date.now();

const byKey = new Map();
for (const e of events) {
  if (!e.key) continue;
  if (!byKey.has(e.key)) byKey.set(e.key, []);
  byKey.get(e.key).push(e);
}

const norm = (s) => String(s ?? '').toLowerCase().trim();
const rows = claims.map(c => {
  if (!c.key) return { ...c, verdict: 'UNRECONCILABLE_NO_KEY' };

  const evs = byKey.get(c.key) || [];
  if (evs.length === 0) {
    const age = c.claimed_at ? now - Date.parse(c.claimed_at) : null;
    // Young and unconfirmed is normal latency. Old and unconfirmed is a real gap.
    return { ...c, verdict: (age != null && age > overdueMs) ? 'MISSING_OVERDUE' : 'PENDING',
             age_minutes: age == null ? null : Math.round(age / 60000) };
  }
  if (evs.some(e => REJECT_STATES.includes(norm(e.state))))
    return { ...c, verdict: 'PROVIDER_REJECTED', provider_states: evs.map(e => e.state) };
  if (evs.some(e => ACCEPT_STATES.includes(norm(e.state))))
    return { ...c, verdict: 'CONFIRMED', provider_states: evs.map(e => e.state) };

  // The provider answered with something we were never told how to read.
  return { ...c, verdict: 'AMBIGUOUS_PROVIDER_STATE', provider_states: evs.map(e => e.state) };
});

// Events the provider has that we never claimed at all - the reverse gap, and it is
// just as real: work happened that our own records do not know about.
const claimKeys = new Set(claims.map(c => c.key).filter(Boolean));
const unclaimed = events.filter(e => e.key && !claimKeys.has(e.key));

const count = (v) => rows.filter(r => r.verdict === v).length;
return [{ json: {
  totals: {
    claimed: claims.length, provider_events: events.length,
    confirmed: count('CONFIRMED'), pending: count('PENDING'),
    missing_overdue: count('MISSING_OVERDUE'), provider_rejected: count('PROVIDER_REJECTED'),
    ambiguous: count('AMBIGUOUS_PROVIDER_STATE'),
    unreconcilable_no_key: count('UNRECONCILABLE_NO_KEY') + 0,
    keyless_claims, unclaimed_provider_events: unclaimed.length
  },
  rows, unclaimed
}}];

// Without this, one stuck record alerts every 15 minutes forever and the whole
// channel gets muted by the humans reading it. Alert fatigue kills monitoring
// faster than missing alerts do.
const state = $getWorkflowStaticData('global');
state.alerted = state.alerted || {};

const win = $('Set reconciliation window and thresholds').first().json;
const cooldownMs = (win.realert_after_hours ?? 24) * 60 * 60 * 1000;
const now = Date.now();

// Forget entries older than twice the cooldown so the store cannot grow without bound.
for (const [k, t] of Object.entries(state.alerted))
  if (now - t > cooldownMs * 2) delete state.alerted[k];

const ACTIONABLE = ['MISSING_OVERDUE','PROVIDER_REJECTED','AMBIGUOUS_PROVIDER_STATE','UNRECONCILABLE_NO_KEY'];
const data = $input.first().json;

const actionable = data.rows.filter(r => ACTIONABLE.includes(r.verdict));
const fresh = actionable.filter(r => {
  const id = `${r.verdict}:${r.key ?? JSON.stringify(r.raw).slice(0, 80)}`;
  const last = state.alerted[id];
  if (last && now - last < cooldownMs) return false;
  state.alerted[id] = now;
  return true;
});

return [{ json: { ...data,
  actionable_count: actionable.length,
  new_since_last_alert: fresh.length,
  suppressed_as_duplicate: actionable.length - fresh.length,
  rows_to_alert: fresh }}];
